import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"🔌 13+ 通信协议接入指南","description":"","frontmatter":{},"headers":[],"relativePath":"iot/protocols.md","filePath":"iot/protocols.md"}'),l={name:"iot/protocols.md"};function r(c,e,d,s,n,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="🔌-13-通信协议接入指南" tabindex="-1">🔌 13+ 通信协议接入指南 <a class="header-anchor" href="#🔌-13-通信协议接入指南" aria-label="Permalink to &quot;🔌 13+ 通信协议接入指南&quot;">​</a></h1><p>MzMedia 内置了广泛的工业与物联通信协议栈，覆盖工业制造、环境监测、园区物联与智慧水务等全品类末端设备：</p><hr><h2 id="协议矩阵详解" tabindex="-1">协议矩阵详解 <a class="header-anchor" href="#协议矩阵详解" aria-label="Permalink to &quot;协议矩阵详解&quot;">​</a></h2><h3 id="_1-mqtt-协议-emqx-5-0-集成" tabindex="-1">1. MQTT 协议 (EMQX 5.0 集成) <a class="header-anchor" href="#_1-mqtt-协议-emqx-5-0-集成" aria-label="Permalink to &quot;1. MQTT 协议 (EMQX 5.0 集成)&quot;">​</a></h3><ul><li><strong>标准规格</strong>：支持 MQTT 3.1、3.1.1、5.0 规范，支持 QoS 0、QoS 1、QoS 2；</li><li><strong>Topic 拓扑设计</strong>： <ul><li>属性上报：<code>/sys/{productKey}/{deviceSecret}/thing/event/property/post</code></li><li>属性设置：<code>/sys/{productKey}/{deviceSecret}/thing/service/property/set</code></li><li>服务调用：<code>/sys/{productKey}/{deviceSecret}/thing/service/{serviceIdentifier}</code></li><li>事件上报：<code>/sys/{productKey}/{deviceSecret}/thing/event/{eventIdentifier}/post</code></li></ul></li></ul><h3 id="_2-modbus-tcp-rtu-协议" tabindex="-1">2. Modbus TCP / RTU 协议 <a class="header-anchor" href="#_2-modbus-tcp-rtu-协议" aria-label="Permalink to &quot;2. Modbus TCP / RTU 协议&quot;">​</a></h3><ul><li>专为工业自动化场景设计，支持读取线圈状态（<code>01</code>）、离散输入（<code>02</code>）、保持寄存器（<code>03</code>）与输入寄存器（<code>04</code>）；</li><li>支持 Master 轮询模式（由网关定时向从站设备轮询数据）与 Slave 被动监听模式；</li><li>支持多种字节序（Big-Endian, Little-Endian, CDAB 等）。</li></ul><h3 id="_3-coap-协议-基于-californium" tabindex="-1">3. CoAP 协议 (基于 Californium) <a class="header-anchor" href="#_3-coap-协议-基于-californium" aria-label="Permalink to &quot;3. CoAP 协议 (基于 Californium)&quot;">​</a></h3><ul><li>面向窄带物联网（NB-IoT）或电池供电的低功耗传感器；</li><li>采用紧凑型二进制报文与 UDP 传输，报文头仅 4 字节，大幅降低硬件耗电量与通信流量。</li></ul><h3 id="_4-tcp-udp-自定义协议" tabindex="-1">4. TCP / UDP 自定义协议 <a class="header-anchor" href="#_4-tcp-udp-自定义协议" aria-label="Permalink to &quot;4. TCP / UDP 自定义协议&quot;">​</a></h3><ul><li>专门应对中小企业老旧设备的非标报文；</li><li>支持定长帧、特殊分隔符帧（如 <code>\\r\\n</code> 或 <code>0x7E</code>）、长度字段前缀帧；</li><li>可配合平台内置的 <strong>AI 协议逆向解析器</strong> 一键生成 Netty 解码器。</li></ul><h3 id="_5-http-rest-webhook" tabindex="-1">5. HTTP REST / Webhook <a class="header-anchor" href="#_5-http-rest-webhook" aria-label="Permalink to &quot;5. HTTP REST / Webhook&quot;">​</a></h3><ul><li>适用于第三方中继系统、车载 GPS 网关的主动 HTTP POST JSON 数据上报；</li><li>支持 Token 鉴权与时间戳签名校验。</li></ul><h3 id="_6-websocket-协议" tabindex="-1">6. WebSocket 协议 <a class="header-anchor" href="#_6-websocket-协议" aria-label="Permalink to &quot;6. WebSocket 协议&quot;">​</a></h3><ul><li>用于前端数字驾驶舱、移动端双向指令下发与设备实时状态全双工同步。</li></ul>',16)])])}const _=o(l,[["render",r]]);export{p as __pageData,_ as default};
